"use client";
import Image from "next/image";import { useEffect,useState } from "react";import { MapPin,Star } from "lucide-react";import { EnquiryForm } from "@/components/marketplace/enquiry-form";
export default function VendorDetail({params}:{params:Promise<{slug:string}>}){const [data,setData]=useState<any>(null);useEffect(()=>{params.then(({slug})=>fetch(`/api/vendors/${slug}`).then(r=>r.ok?r.json():null).then(setData))},[params]);if(!data)return <div className="min-h-screen bg-ivory px-5 pt-40 text-center">Loading profile...</div>;const v=data.vendor;return <main className="bg-ivory pb-24 pt-28"><div className="mx-auto max-w-7xl px-5 sm:px-8"><div className="relative h-[420px] overflow-hidden rounded-[2rem]"><Image src={v.profileImage} alt={v.name} fill className="object-cover" sizes="100vw"/><div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/10 to-transparent"/><div className="absolute bottom-0 left-0 p-7 text-white sm:p-10"><p className="text-xs font-semibold uppercase tracking-[0.3em] text-gold">{v.category}</p><h1 className="mt-2 font-display text-5xl">{v.name}</h1><p className="mt-2 flex items-center gap-2 text-white/75"><MapPin size={16}/>{v.city}</p></div></div><div className="mt-10 grid gap-10 lg:grid-cols-[1.2fr_.8fr]"><div><div className="flex flex-wrap gap-5 text-sm"><span className="flex items-center gap-1"><Star size={16} className="fill-gold text-gold"/>{v.rating.toFixed(1)} ({v.reviewCount} reviews)</span><strong>₹{v.startingPrice.toLocaleString("en-IN")} {v.pricingUnit === "per_plate" ? "/ plate" : "starting"}</strong></div><p className="mt-7 leading-8 text-charcoal/65">{v.description}</p><h2 className="mt-10 font-display text-3xl">Packages</h2><div className="mt-5 grid gap-4 md:grid-cols-3">{v.packages.map((p:any)=><div key={p.name} className="rounded-2xl bg-white p-5"><h3 className="font-semibold">{p.name}</h3><p className="mt-2 font-display text-2xl">₹{p.price.toLocaleString("en-IN")}</p><p className="mt-2 text-sm text-charcoal/55">{p.description}</p></div>)}</div><h2 className="mt-10 font-display text-3xl">Portfolio</h2><div className="mt-5 grid grid-cols-2 gap-3 md:grid-cols-3">{v.portfolioImages.map((img:string)=><div key={img} className="relative aspect-square overflow-hidden rounded-2xl"><Image src={img} alt={v.name} fill className="object-cover" sizes="33vw"/></div>)}</div><h2 className="mt-10 font-display text-3xl">Reviews</h2><div className="mt-5 space-y-4">{data.reviews.length?data.reviews.map((r:any)=><div key={r._id} className="rounded-2xl bg-white p-5"><div className="flex justify-between"><strong>{r.userName}</strong><span>★ {r.rating}</span></div><p className="mt-2 text-sm text-charcoal/60">{r.comment}</p></div>):<p className="text-charcoal/50">No reviews yet.</p>}</div></div><EnquiryForm vendorId={v._id} title="Enquire with this professional"/></div></div></main>}
